insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-6-foundation-vector-tools',6,'Day 6 · Foundation: Vector addition and decomposition',array['u1.vectors-tip-to-tail'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-6','day-6-foundation-vector-tools','day-6-vectors',array['f6-translate','f6-route','f6-scale','f6-add','f6-asteroid','f6-components','f6-angle','f6-quadrant','f6-exit-sum','f6-exit-angle'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-3c','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 6 · Quiz: Vector addition and decomposition","instructions":"Work independently after submitting the foundation and review. Sketch your axes and reference angles, use degree mode and include units. Your teacher releases the quiz grade and reviews mastery separately.","questions":[{"kind":"choice","prompt":"Which change preserves a vector when constructing a tip-to-tail sum?","options":["Rotate it through 90°","Double its drawn length at the same scale","Translate it with its length and direction unchanged","Reverse its arrowhead"],"correct_index":2,"guide":"Translation preserves the magnitude and direction of a vector.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Identifies a valid tip-to-tail transformation."}},{"kind":"choice","prompt":"A walker goes 5 m east then 12 m north. Which pair gives path distance and displacement magnitude?","options":["17 m and 17 m","17 m and 13 m","13 m and 17 m","7 m and 13 m"],"correct_index":1,"guide":"Path distance is 5 + 12 = 17 m. Displacement magnitude is √(5² + 12²) = 13 m.","points":1,"demand":{"blooms":"Apply","dok":2,"evidence":"Distinguishes the length of a two-leg route from its resultant."}},{"kind":"choice","prompt":"A 16 N force points 30° east of north. With east as +x, what is its x component?","options":["+13.9 N","−8 N","+16 N","+8 N"],"correct_index":3,"guide":"The x component is opposite the angle from north: 16 sin 30° = +8 N.","points":1,"demand":{"blooms":"Apply","dok":2,"evidence":"Chooses the correct projection for an angle measured from the vertical."}},{"kind":"choice","prompt":"A displacement has components (−5, +12) m, with east and north positive. In which direction does it point?","options":["Northwest","Northeast","Southeast","Southwest"],"correct_index":0,"guide":"Negative x points west and positive y points north, so the resultant points northwest.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Interprets component signs as a quadrant."}},{"kind":"written","prompt":"With east and north positive, add A = (+2, −3) m and B = (−8, −5) m. Give resultant components, magnitude and direction south of west. Explain how your sketch and a component reconstruction check the direction.","guide":"R = (−6, −8) m; magnitude 10 m; angle tan⁻¹(8/6) ≈ 53.1° south of west. Sketch southwest. Reconstruct x = −10 cos 53.1° ≈ −6 m and y = −10 sin 53.1° ≈ −8 m. Equivalent 233.1° counterclockwise from east is valid.","points":3,"demand":{"blooms":"Analyze","dok":2,"evidence":"Adds signed components and verifies a direction in a new quadrant."}},{"kind":"written","prompt":"A 14 m/s velocity points 60° west of north, equivalently 30° north of west. A student says, “Cosine always gives x, so x = +14 cos 60° = +7 m/s.” Evaluate this method. Find both correct signed components and demonstrate that both angle descriptions give the same vector.","guide":"x = −14 sin 60° = −14 cos 30° ≈ −12.12 m/s; y = +14 cos 60° = +14 sin 30° = +7 m/s. The adjacent component depends on the reference axis; west makes x negative. Both descriptions reconstruct magnitude 14 m/s with the same northwest direction. A complete critique addresses the wrong reference-axis formula and the wrong sign.","points":3,"demand":{"blooms":"Evaluate","dok":3,"evidence":"Critiques a method and validates signed components through two equivalent reference angles."}}]}'::jsonb);
